[DataContractAttribute]
class AVACRLUpdateRiscDebtorContract
{
    protected CustAccount             riscDebtor;
    str                               qryStr;
    protected DataAreaId              company;

}

Method.Source:
/// <summary>
/// parm method for specified or saved riskDebtor
/// </summary>
/// <param name = "_riscDebtor">CustAccount</param>
/// <returns>CustAccount</returns>
public CustAccount parmRiscDebtor(CustAccount _riscDebtor = riscDebtor)
{
    riscDebtor = _riscDebtor;
    return riscDebtor;
}

public DataAreaId parmCompany(DataAreaId _company = company)
{
    company = _company;
    return company;
}

/// <summary>
/// parm method for query
/// </summary>
/// <param name = "_qryStr">str</param>
/// <returns>str</returns>
[
DataMemberAttribute
,AifQueryTypeAttribute('_qryStr', '')
]
public str parmQuery(str _qryStr = qryStr)
{
    qryStr = _qryStr;
    return qryStr;
}
